        "server.extensions.ask-someone.description.write-question-someone-outside":
            "Write a question for someone outside this chat, such as a manager, a client, or an expert, who has not seen it. Use it when the person asks to ask someone else, or when a decision needs someone who is not here and the person agrees. Nothing is sent: it saves a draft that the person reviews, edits, and then shares as a link or as text. The question must stand alone: give the background the reader needs, the question itself, the options with their costs, and your recommendation. Keep it short and plain. Leave out keys, passwords, private data, and internal details that the reader does not need.",
