        "server.extensions.design.messages.system-request.text.scan-project-make-design":
            "Scan this project and make a design system for it with the design_system tool: the colors as a palette and as named roles (page, surface, text, muted, border, accent, and the statuses), light and dark modes, a type scale, spacing, corner radii, shadows, and motion, and component specimens for the main controls. Save it, then tell me what you found.",
        "server.extensions.design.messages.system-request.text.project-design-system-markdown":
            "This project has a design system in Markdown (.pi/design-system.md). Convert it into the structured design system with the design_system tool: the same colors, type, spacing, and rules, as tokens with named roles, light and dark modes, and component specimens. Keep every value, and tell me what you changed.",
        "server.extensions.design.messages.system-request.text.add-component-specimens-design":
            "Add component specimens to the design system with the design_system tool for the core controls (a button, a text field, a card, a badge, and a switch), each with its states: default, hover, focus, disabled, and error where it applies. Use only the system's tokens.",
        "server.extensions.design.messages.system-request.text.add-one-more-component":
            "Add one more component specimen to the design system with the design_system tool. If it is not clear which one, ask me first. Use only the system's tokens, and give it every state it has.",
        "server.extensions.design.messages.system-request.text.write-guidelines-design-system":
            "Write guidelines for the design system with the design_system tool, in Markdown: the voice, the layout, the use of color and type, and a list of do and don't. Base them on what the tokens and components already say.",
