        "server.design.tokens-names.names-markdown.lines.names": "# 名称：{name}",
        "server.design.tokens-names.names-markdown.lines.generated-pi-pocket-design":
            "由 Pi Pocket 根据 `.pi/design/` 生成。不要手动编辑：修改设计令牌后重新编译。",
        "server.design.tokens-names.names-markdown.lines.token-name-three-places":
            "每个设计令牌有三处名称：`tokens.css` 中的变量、`tailwind.css` 中的变量，以及 Tailwind 根据该变量生成的工具类。在 CSS 中使用变量（`var(--color-bg-surface)`），在 Tailwind 标记中使用类（`bg-surface`）。",
        "server.design.tokens-names.names-markdown.lines.names-come-out": "## 名称生成方式",
        "server.design.tokens-names.names-markdown.lines.tokens-css-path-token":
            "- **`tokens.css`**：设计令牌路径用 `-` 连接，并加 `--` 前缀。`color.bg.surface` 生成 `--color-bg-surface`，不再增删内容。",
        "server.design.tokens-names.names-markdown.lines.tailwind-css-variable-namespace":
            "- **`tailwind.css`**：变量放入符合设计令牌类型的 Tailwind v4 命名空间，以生成正确工具类：`--color-*`、`--font-*`（字体族）、`--text-*`、`--font-weight-*`、`--tracking-*`、`--leading-*`、`--breakpoint-*`、`--container-*`、`--spacing-*`、`--radius-*`、`--shadow-*`、`--inset-shadow-*`、`--drop-shadow-*`、`--blur-*`、`--perspective-*`、`--aspect-*`、`--ease-*`。不匹配任何命名空间时保留 `tokens.css` 名称（`--button-height`）；名称会被误读为其他类型命名空间时，加 `--ds-` 前缀。",
        "server.design.tokens-names.names-markdown.lines.color-roles-drop-word":
            "- **颜色角色**省略工具类已表达的词：`color.bg.surface` 生成 `--color-surface`，类名为 `bg-surface`，而非 `bg-bg-surface`；`color.text.muted` 生成 `text-muted`；`color.border.subtle` 生成 `border-subtle`。",
        "server.design.tokens-names.names-markdown.lines.role-default-primary-secondary":
            "- **仅含 `default`、`primary`、`secondary`、`tertiary`、`base`、`main`、`normal`、`regular` 或 `standard` 的角色**单独使用无法明确含义（`primary` 也可指品牌色），因此采用组名：`color.border.default` 生成 `--color-border`，`color.text.primary` 生成 `--color-text`，`color.bg.base` 生成 `--color-bg`。这些组以外的末尾 `default` 会省略：`color.accent.default` 生成 `--color-accent`。",
        "server.design.tokens-names.names-markdown.lines.two-tokens-want-one":
            "- **两个设计令牌生成同名变量时**：文件中靠前者保留短名，另一项保留完整名称（`color.text.secondary` 生成 `--color-text-secondary`）。",
        "server.design.tokens-names.names-markdown.lines.every-color-makes-bg":
            "- 每个颜色均生成 `bg-`、`text-`、`border-`、`ring-`、`fill-` 和 `stroke-` 工具类。表格显示角色组名对应的工具类；其他类也可使用。",
        "server.design.tokens-names.names-markdown.text.token-tokens-css-tailwind":
            "| 设计令牌 | `tokens.css` | `tailwind.css` | 工具类 |",
