        "builtin.module.prompt.summary":
            "定义代理身份、手机界面的行为、Pi Pocket 文档位置、项目 AGENTS.md、Pi 技能及工作目录。",
        "builtin.module.artifacts.summary":
            "代理发布 HTML 页面、Markdown 文档和 SVG 图片，供用户在应用内打开；也可用 artifact_inline 在回复中显示同一存储中的页面卡片。",
        "builtin.module.browser.summary":
            "Pi 使用本机真实 Chromium 打开、读取、点击网页并截图。会话成员可以在浏览器面板查看和操作同一页面。",
        "builtin.module.subagents.summary": "持久化后台子代理，基于 Pi Durable 示例 23。",
        "builtin.module.agent-teams.summary":
            "代理团队让 Pi 启动独立的关联会话，并向它们发送任务、问题和发现。",
        "builtin.module.schedules.summary":
            "定时消息会在稍后或周期性发送给 Pi。成员使用 /schedule，Pi 使用 schedule 工具，跟进耗时工作或执行例行任务。",
        "builtin.module.background.summary":
            "后台任务让 Pi 启动命令后无需等待，例如开发服务器、长构建或测试。Pi 可稍后读取输出或停止命令，并在命令结束时收到通知。",
        "builtin.module.goals.summary":
            "Pi 持续工作，直到会话的检查命令通过，例如 npm test；最多检查五次。",
        "builtin.module.plan.summary":
            "计划模式允许 Pi 读取和探索，但不做修改。Pi 先提出计划，由成员批准。",
        "builtin.module.anthropic-subscription.summary":
            "添加请求头，让 Anthropic 将 Pi Pocket 请求计入 Claude 订阅。",
        "builtin.module.guard.summary": "为 Pi Pocket 工具提供 Lancet Guard 检查。",
        "builtin.module.codemode.summary":
            "Codemode 让代理编写 JavaScript 调用其他工具，以批量执行独立调用、串联调用或在输出进入模型前过滤大量结果。",
        "builtin.module.memory.summary":
            "记忆让 Pi 提出跨会话保留的项目或全局经验。所有者在工具调用下方或菜单中的记忆页批准后，后续会话的系统提示会包含这些经验。",
        "builtin.module.pip.summary":
            "PiP 是跨界面的个人助手。它查看会话状态、创建和发送任务、停止或归档会话、设置定时消息、跟进任务、监视 GitHub 仓库和拉取请求，并可拒绝等待审批的调用，但不能批准。",
        "builtin.module.triggers.summary":
            "触发器从应用外启动工作。拉取请求监视会在检查失败、发生冲突或收到评审时通知 Pi；仓库监视向 PiP 报告仓库事件；网络钩子把外部服务的提交转为发给会话或 PiP 的消息。",
        "builtin.module.gallery.summary":
            "在已审核索引中查找他人的扩展和主题，安装后保持扩展关闭，阅读代码、请 Pi 审查、查看差异并更新、移除，或分享自己的作品。",
        "builtin.module.session-tags.summary": "在会话行显示共享标签，支持搜索和筛选会话列表。",
        "builtin.module.ask.summary":
            "Pi 在会话卡片中提出最多 4 个问题。每题提供 2 至 4 个可选答案，也可输入自己的答案。",
        "builtin.module.ask-someone.summary":
            "Pi 起草可由聊天外的人回答的问题，成员通过链接或文本分享。",
        "builtin.module.updates.summary":
            "每 6 小时检查 Pi Pocket 新版本，通知所有者并显示更新说明。可一键更新 Git 工作树或全局 npm 安装并重启，也可在没有会话工作时自动安装。",
        "builtin.module.design.summary": "在聊天旁提供交互式设计画布。",
        "builtin.module.tool-search.summary":
            "工具搜索把少数会话才使用的工具移出常规请求，直到 Pi 主动请求。",
        "builtin.module.zh-cn.summary": "简体中文界面文案。在外观中选择，关闭此模块后移除。",
